import java.util.*;

record Entry(String thread, String state, String resource) { }

public class Main {
    public static void main(String[] a) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        List<Entry> entries = new ArrayList<>();
        for (int i = 0; i < n; i++) entries.add(new Entry(sc.next(), sc.next(), sc.next()));
        List<Entry> blocked = entries.stream().filter(e -> e.state().equals("BLOCKED")).sorted(Comparator.comparing(Entry::thread)).toList();
        if (blocked.isEmpty()) System.out.println("NONE");
        else blocked.forEach(e -> System.out.println(e.thread() + " waits " + e.resource()));
    }
}

