import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        Map<Thread.State, Integer> counts = new EnumMap<>(Thread.State.class);
        for (int i = 0; i < n; i++) {
            String name = sc.next();
            Thread.State state = Thread.State.valueOf(sc.next());
            counts.merge(state, 1, Integer::sum);
        }
        for (Thread.State st : Thread.State.values()) if (counts.containsKey(st)) System.out.println(st + "=" + counts.get(st));
        int blocked = counts.getOrDefault(Thread.State.BLOCKED, 0);
        int waiting = blocked + counts.getOrDefault(Thread.State.WAITING, 0) + counts.getOrDefault(Thread.State.TIMED_WAITING, 0);
        int runnable = counts.getOrDefault(Thread.State.RUNNABLE, 0);
        System.out.println("waiting=" + waiting + " runnable=" + runnable);
        if (blocked > 0) System.out.println("CHECK_LOCK_CONTENTION");
        else if (waiting > runnable) System.out.println("CHECK_WAITING_CAUSE");
        else System.out.println("NEEDS_MORE_EVIDENCE");
    }
}

