import java.util.*;

public class Main {
    static long[] measured(Scanner sc, int warmup, int m) {
        for (int i = 0; i < warmup; i++) sc.nextLong();
        long[] xs = new long[m];
        for (int i = 0; i < m; i++) xs[i] = sc.nextLong();
        return xs;
    }

    static long p50(long[] xs) {
        long[] sorted = Arrays.copyOf(xs, xs.length);
        Arrays.sort(sorted);
        int rank = (50 * sorted.length + 99) / 100;
        return sorted[rank - 1];
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int warmup = sc.nextInt(), m = sc.nextInt();
        long before = p50(measured(sc, warmup, m)), after = p50(measured(sc, warmup, m));
        System.out.println("before p50=" + before + " after p50=" + after);
        if (before == 0) {
            System.out.println("improvement=NA");
            System.out.println("NO_CHANGE");
            return;
        }
        long improvement = (before - after) * 100 / before;
        System.out.println("improvement=" + improvement + "%");
        System.out.println(improvement >= 5 ? "KEEP" : improvement < - 5 ? "REVERT" : "NO_CHANGE");
    }
}
